1	/**
2	 * "Match my approved picture" test switches for the gameplay screens (2026-11-17, qa/match/NOTES.md).
3	 *   `?match02=1` … `?match10=1`  one screen each (05 has its own set; `?match05=1` turns all of those on — see
4	 *   src/vfx/waterRibbon.ts q05). `?matchall=1` = every screen switch below at once.
5	 * Every change a screen makes lives behind its switch: with no switch the game is byte-for-byte the default build
6	 * (verified by pixel comparison after every change). Packaged experiment builds read the same keys from
7	 * VITE_RAINBOW_Q05 (flag05).
8	 * File ownership (one owner per screen while work runs in parallel): see qa/match/NOTES.md.
9	 */
10	import type { CamParams } from './cameraRig';
11	import { flag05 } from '../vfx/waterRibbon';
12	
13	export type MatchId = '02' | '03' | '04' | '06' | '07' | '08' | '09' | '10';
14	export const MATCH_IDS: MatchId[] = ['02', '03', '04', '06', '07', '08', '09', '10'];
15	const ALL = flag05('matchall');
16	export const MATCH: Record<MatchId, boolean> = Object.fromEntries(MATCH_IDS.map((id) => [id, ALL || flag05('match' + id)])) as Record<MatchId, boolean>;
17	export const matchOn = (id: string): boolean => (MATCH as Record<string, boolean>)[id] === true;
18	
19	/**
20	 * Camera framing per screen under its switch (merged over cameraRig STAGE_CAM by applyMatchCam): the checkpoint
21	 * camera is the approved picture's camera — Benny's size and place, the vanishing point and the horizon.
22	 * Measured with scripts/match-cam-try.mjs; one line per screen (owner: that screen's worker).
23	 */
24	export const MATCH_CAM: Partial<Record<MatchId, Partial<CamParams>>> = {
25	  '07': { back: 9, up: 5.4, ahead: 22, lookUp: -1.8, fov: 62 },
26	};
27	
28	/** called once by cameraRig after STAGE_CAM is defined */
29	export function applyMatchCam(stageCam: Partial<Record<string, CamParams>>): void {
30	  for (const id of MATCH_IDS) {
31	    const o = MATCH_CAM[id];
32	    if (!MATCH[id] || !o || !stageCam[id]) continue;
33	    stageCam[id] = { ...(stageCam[id] as CamParams), ...o };
34	  }
35	}
36

1	/**
2	 * RAINBOW master course — ONE continuous route through the washer world.
3	 *
4	 * Units: 1 unit ≈ 5 cm at Benny's scale (Benny body radius ≈ 0.8). +Y is up (absolute altitude).
5	 * The route starts inside Drum A (scene 01/02), drains through a chute into the whirlpool basin (03),
6	 * drops down the five-arrow slide (04), winds through the perforated current tube (05), crests the
7	 * rinse arch (06), winds through the washer tube and then PLUNGES ~62 units straight down (07) before
8	 * the bottom of that same tube flares into the Final Spin Chamber inlet (08). 08–10 stay in that same
9	 * chamber; the route ends under the purple towel on the platform, where the 11 cinematic plays.
10	 *
11	 * Every stage is a range of arc-length `s` on a single centripetal Catmull-Rom spline, so position
12	 * and tangent are continuous by construction; `validateContinuity()` measures it anyway.
13	 */
14	import * as THREE from 'three';
15	
16	export type StageId = '01' | '02' | '03' | '04' | '05' | '06' | '07' | '08' | '09' | '10' | '11';
17	export type TubeKind = 'none' | 'chute' | 'gold' | 'perf';
18	export type StageProp = 'width' | 'tube' | 'speed' | 'bank';
19	
20	export interface StageDef {
21	  id: StageId;
22	  title: string;
23	  /** arc-length range on the course */
24	  s0: number;
25	  s1: number;
26	  /** water ribbon width (units) */
27	  width: number;
28	  /** enclosing tube radius (0 = open environment such as a drum/basin/chamber) */
29	  tube: number;
30	  tubeKind: TubeKind;
31	  /** auto-propulsion speed (units / s) */
32	  speed: number;
33	  /** coin counter shown in the locked reference screenshot of this stage */
34	  refCoins: number;
35	  interactive: boolean;
36	  /** banking strength multiplier */
37	  bank: number;
38	}
39	
40	export interface CourseSample {
41	  s: number;
42	  pos: THREE.Vector3;
43	  tan: THREE.Vector3;
44	  up: THREE.Vector3;
45	  right: THREE.Vector3;
46	}
47	
48	export const STAGE_TITLES: Record<StageId, string> = {
49	  '01': 'INSIDE THE WASHING MACHINE',
50	  '02': 'WHIRLPOOL TUMBLE',
51	  '03': 'WHIRLPOOL TWIRL',
52	  '04': 'THROUGH THE FIVE ARROWS',
53	  '05': 'FLOW INTO THE CURRENT',
54	  '06': 'CREST THE RINSE ARCH',
55	  '07': 'DIVE THE WASHER TUBE',
56	  '08': 'FINAL SPIN CHAMBER',
57	  '09': 'RIDE THE FINAL WAVE',
58	  '10': 'SLIDE INTO HIDING',
59	  '11': 'SAFELY HOME',
60	};
61	
62	/** Fixed world anchors shared by environment builders (absolute coordinates). */
63	export const WORLD = {
64	  drumA: { center: new THREE.Vector3(0, 0, 0), radius: 5, zBack: -6.5, zDoor: 3.5, doorRadius: 3.2, waterY: -2.5 },
65	  basin: { center: new THREE.Vector3(2, -16, -19), rimRadius: 11.5, rimY: -10.6, drainRadius: 4.3, drainY: -20.2 },
66	  /** Final Spin Chamber (08–11): drum with axis along Z, door at the far (-Z) end */
67	  chamber: { center: new THREE.Vector3(12, -101.1, 0), radius: 13.5, zBack: -280, zDoor: -332, floorY: -113.6, doorRadius: 6.2 },
68	  platform: { center: new THREE.Vector3(12, -110.6, -325.0), radius: 6.2, topY: -110.6 },
69	  plunge: { topY: -52, bottomY: -113.6 },
70	};
71	
72	/** funnel surface height of the whirlpool basin as a function of radius from its axis */
73	export function funnelY(r: number): number {
74	  const b = WORLD.basin;
75	  const t = THREE.MathUtils.clamp((r - b.drainRadius * 0.6) / (b.rimRadius - b.drainRadius * 0.6), 0, 1);
76	  return b.drainY + (b.rimY - b.drainY) * Math.pow(t, 0.72);
77	}
78	
79	const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);
80	const smooth = (a: number, b: number, x: number) => {
81	  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
82	  return t * t * (3 - 2 * t);
83	};
84	
85	/**
86	 * A stretch whose tunnel axis is an exact straight line a→b (the stream winds inside it). The
87	 * course lies on the line at both ends of the stretch; tube.ts aligns the tunnel axis to it.
88	 */
89	export interface StraightAxis {
90	  /** arc-length range of the stretch on the course */
91	  s0: number;
92	  s1: number;
93	  a: THREE.Vector3;
94	  b: THREE.Vector3;
95	  /** stream-to-tunnel-bottom depth on the line (water sits this high in the tube) */
96	  floorDepth: number;
97	}
98	
99	interface RouteData {
100	  points: THREE.Vector3[];
101	  marks: Record<string, number>;
102	  straight: { from: string; to: string; a: THREE.Vector3; b: THREE.Vector3; floorDepth: number }[];
103	}
104	
105	/**
106	 * 05 current (ref 05): the tunnel is a straight line; the STREAM winds inside it. The meander is the
107	 * lateral (world +X) offset of the course centreline from that line, as a function of the distance
108	 * `u` along the line (0 … L05). It is applied to the route AFTER smoothPolyline, so it is exact (the
109	 * smoothing would shave ~25 % off the amplitude) and still C¹ at both ends (offset and slope → 0).
110	 *
111	 * Shape tuned against the reference's cyan core: a small first crest under Benny at the 05
112	 * checkpoint (u≈uCrest, offset a0 to the LEFT, heading parallel to the tunnel axis), then crests
113	 * that grow toward the far end (screen: Benny → (560,700) → (450,600) → (520,520) → VP).
114	 * Coins (gameplay/coins.ts) sit on this centreline (lat 0), so they wind with the same S.
115	 */
116	export const S05 = {
117	  /** length of the straight tunnel line (units) */
118	  L: 72,
119	  /** wavelength along the line (crest → crest of the same side) */
120	  lambda: 32,
121	  /** u of the first (left) crest, where Benny rides at the 05 checkpoint */
122	  uCrest: 14,
123	  /** crest amplitude at uCrest and at uCrest + 1.5 λ (linear growth in between) */
124	  a0: 0.45,
125	  a1: 1.85,
126	  /** half extent of the stream (|offset| + half width) in the current: fills the tube floor */
127	  extent: 6.0,
128	};
129	
130	/**
131	 * 05 meander AHEAD of Benny's crest (u > uCrest): [u, offset] knots fitted to the APPROVED reference (wave 6
132	 * camera lock, qa/pilot05/wave6/camera_lock/landmarks.json). The reference's coin trail was back-projected
133	 * through the live locked 05 camera onto the river (coin height 1.2 u) and converted to offsets from the
134	 * tunnel line; coins sit at (1 + latK·CORE_SWING) ≈ 1.62 × the course offset, so knot = coin offset / 1.62.
135	 * Ref coins (px → u, coin offset): (474,726)→21.6,−0.31 · (548,661)→26.3,+0.60 · (482,612)→32.2,−0.37 ·
136	 * (431,574)→43.0,−1.85 · (466,546)→55.5,−1.28 · (495,533)→67.0,−0.26. The previous sine (λ 32) put the right
137	 * swing at u≈30–33 and +1.45 wide, so the 3rd coin sat ≈100 px right of the reference.
138	 * Interpolation: C¹ cubic Hermite (non-uniform Catmull-Rom tangents), slope 0 at the crest and at L.
139	 */
140	const MEANDER05_KNOTS: [number, number][] = [[26.3, 0.37], [32.2, -0.23], [43, -1.14], [55.5, -0.79]];
141	
142	/** the original (wave 1–5) sine meander; kept verbatim up to U05_KEEP so the 04→05 join, the '05_crest'
143	 *  checkpoint search window (u ≤ uCrest + λ/4) and therefore the LOCKED 05 camera are bit-identical */
144	function meander05Sine(u: number): number {
145	  const { L, lambda, uCrest, a0, a1 } = S05;
146	  const grow = THREE.MathUtils.clamp((u - uCrest) / (1.5 * lambda), 0, 1);
147	  const amp = (a0 + (a1 - a0) * grow) * smooth(0, 10, u) * (1 - smooth(L - 12, L, u));
148	  return -amp * Math.cos((2 * Math.PI * (u - uCrest)) / lambda);
149	}
150	const U05_KEEP = S05.uCrest + S05.lambda / 4;
151	
152	/** C¹ cubic Hermite through knots (non-uniform Catmull-Rom tangents; end slopes given) */
153	function hermiteKnots(k: [number, number][], u: number, m0: number, mN = 0): number {
154	  const n = k.length;
155	  if (u >= k[n - 1][0]) return k[n - 1][1];
156	  let i = 0;
157	  while (u > k[i + 1][0]) i++;
158	  const tan = (j: number) => (j === 0 ? m0 : j === n - 1 ? mN : (k[j + 1][1] - k[j - 1][1]) / (k[j + 1][0] - k[j - 1][0]));
159	  const [u0, p0] = k[i], [u1, p1] = k[i + 1];
160	  const h = u1 - u0, t = (u - u0) / h, t2 = t * t, t3 = t2 * t;
161	  return (2 * t3 - 3 * t2 + 1) * p0 + (t3 - 2 * t2 + t) * h * tan(i) + (-2 * t3 + 3 * t2) * p1 + (t3 - t2) * h * tan(i + 1);
162	}
163	/** from U05_TAIL to the 06 join the ORIGINAL curve is used verbatim, so the 05→06 junction (and the 06 up-vector
164	 *  smoothing, which looks ±12 samples back into 05) is bit-identical to the approved 06 */
165	const U05_TAIL = 67;
166	const slopeOf = (f: (u: number) => number, u: number) => (f(u + 1e-3) - f(u - 1e-3)) / 2e-3;
167	const KNOTS05: [number, number][] = [[U05_KEEP, meander05Sine(U05_KEEP)], ...MEANDER05_KNOTS, [U05_TAIL, meander05Sine(U05_TAIL)]];
168	const SLOPE05_KEEP = slopeOf(meander05Sine, U05_KEEP);
169	const SLOPE05_TAIL = slopeOf(meander05Sine, U05_TAIL);
170	
171	/**
172	 * 05 EXIT BEND (u 56–67, sin², C¹: zero value and slope at both ends): the original course swung right
173	 * here before the 06 arch too (old sine +1.71 u at u 62). Its amplitude is solved (secant on Course.length)
174	 * so the route keeps EXACTLY its old length 435.193. Why the length must stay: besides geometry, the water
175	 * wave/flow phase, Benny's float bob, foam lumps and bubbles are keyed on absolute s, so a shorter 05
176	 * (−0.78 u) shifted every later screen (06: Benny 0.034 lower, a ring grazing the frame bottom, different
177	 * bubbles/foam). The 06/07 rings, lids and slot rows are additionally anchored to the 06 stage start
178	 * (environment.ts STAGE ANCHORS) as a safety net.
179	 */
180	const EXIT05_BEND = { u0: 56, u1: U05_TAIL, amp: 1.353668 };
181	
182	/** lateral offset (units, + = world +X = rider's right when heading -Z) of the 05 stream from its tunnel line */
183	export function meander05(u: number): number {
184	  if (u <= 0 || u >= S05.L) return 0;
185	  if (u <= U05_KEEP || u >= U05_TAIL) return meander05Sine(u);
186	  const { u0, u1, amp } = EXIT05_BEND;
187	  const bend = u > u0 && u < u1 ? amp * Math.sin((Math.PI * (u - u0)) / (u1 - u0)) ** 2 : 0;
188	  return hermiteKnots(KNOTS05, u, SLOPE05_KEEP, SLOPE05_TAIL) + bend;
189	}
190	
191	/** Generates the dense control polyline of the route (absolute coordinates). */
192	function buildRoute(): RouteData {
193	  const pts: THREE.Vector3[] = [];
194	  const marks: Record<string, number> = {};
195	  const straight: RouteData['straight'] = [];
196	  const push = (p: THREE.Vector3) => {
197	    if (pts.length && p.distanceTo(pts[pts.length - 1]) < 0.25) return;
198	    pts.push(p);
199	  };
200	  const mark = (k: string) => (marks[k] = pts.length - 1);
201	  const seg = (n: number, f: (t: number) => THREE.Vector3, skipFirst = true) => {
202	    for (let i = skipFirst ? 1 : 0; i <= n; i++) push(f(i / n));
203	  };
204	
205	  // ---- 01: Benny hidden in the towel, drum A front-left floor (camera looks toward the door) ----
206	  const dA = WORLD.drumA;
207	  const hc = V(0, -0.4, 0); // swirl axis
208	  const th0 = Math.atan2(-2.0, 1.6);
209	  push(V(1.6, -2.4, -2.2));
210	  mark('01');
211	  // ---- 02: whirlpool tumble — helix around the drum axis toward the back drain ----
212	  const thEnd = -Math.PI / 2 - Math.PI * 2;
213	  seg(26, (t) => {
214	    const th = th0 + (thEnd - th0) * t;
215	    const r = 2.56 + (3.9 - 2.56) * smooth(0, 1, t);
216	    const z = -2.2 + (-5.4 + 2.2) * t;
217	    return V(hc.x + r * Math.cos(th), hc.y + r * Math.sin(th), z);
218	  });
219	  mark('02_drain');
220	  // chute from drum A back drain down into the whirlpool basin rim
221	  const b = WORLD.basin;
222	  const spiralStart = V(b.center.x - 9.6, funnelY(9.6) + 0.25, b.center.z);
223	  const c0 = pts[pts.length - 1].clone();
224	  const chuteCtrl = [c0, V(-0.6, -5.6, -7.6), V(-3.2, -7.8, -10.4), V(-6.6, -9.8, -14.2), spiralStart.clone().add(V(0, 0.15, 2.4))];
225	  const chute = new THREE.CatmullRomCurve3(chuteCtrl, false, 'centripetal');
226	  seg(14, (t) => chute.getPoint(t));
227	  push(spiralStart);
228	  mark('03');
229	  // ---- 03: whirlpool twirl — 3/4 inward turn down the funnel that dives into the drain CENTRE ----
230	  // decreasing angle from the -X side (θ=-π/2) round the far and right sides to the near (+Z) side;
231	  // r shrinks as (1-t)^1.6 so the last stretch heads radially inward = straight -Z into the drain hole.
232	  seg(60, (t) => {
233	    const th = -Math.PI / 2 - Math.PI * 1.5 * (1 - (1 - t) * (1 - t)); // angle eases out → radial finish
234	    const r = 9.6 * Math.pow(1 - t, 0.9);
235	    return V(b.center.x + r * Math.sin(th), funnelY(r) + 0.25, b.center.z + r * Math.cos(th));
236	  });
237	  mark('04');
238	  // ---- 04: five-arrow slide — steep straight drop (≈32°) inside the gold ring pipe ----
239	  const s4 = pts[pts.length - 1].clone();
240	  const pitch4 = THREE.MathUtils.degToRad(32);
241	  const d4 = V(0, -Math.sin(pitch4), -Math.cos(pitch4));
242	  // pull-down arc from the drain lip into the steep slide pitch
243	  const R4a = 9;
244	  seg(7, (t) => {
245	    const a = pitch4 * t;
246	    return s4.clone().add(V(0, -R4a * (1 - Math.cos(a)), -R4a * Math.sin(a)));
247	  });
248	  const s4b = pts[pts.length - 1].clone();
249	  seg(16, (t) => s4b.clone().addScaledVector(d4, 34 * t));
250	  // pull out of the slide into the horizontal current
251	  const s4c = pts[pts.length - 1].clone();
252	  const R4 = 12;
253	  seg(8, (t) => {
254	    const a = -pitch4 + pitch4 * t;
255	    return s4c.clone().add(V(0, R4 * (Math.cos(-pitch4) - Math.cos(a)), R4 * (Math.sin(-pitch4) - Math.sin(a))));
256	  });
257	  mark('05');
258	  // ---- 05: long STRAIGHT perforated current tube (ref 05: concentric rings, ONE vanishing point);
259	  // the wide stream winds in S-curves inside it. Here only the straight line s5 → s5+L05 (slight
260	  // descent) is laid; the lateral S-offset meander05(u) is added after smoothing (see the end of
261	  // buildRoute). Offset and slope vanish at both ends, so 04 and 06 join tangentially and s6 (hence
262	  // 06/07/plunge/08) is unchanged. tube.ts builds the 05 tunnel on the line.
263	  const s5 = pts[pts.length - 1].clone();
264	  const L05 = V(0, -3, -S05.L);
265	  // 48 points (1.5-unit spacing) as before: the junction smoothing, hence the 04/05 and 05/06 stage
266	  // boundaries and the 06 checkpoint, stay exactly where they were
267	  seg(48, (t) => s5.clone().addScaledVector(L05, t));
268	  straight.push({ from: '05', to: '06', a: s5.clone(), b: s5.clone().add(L05), floorDepth: 3.3 });
269	  mark('06');
270	  // ---- 06: rinse arch — rises ~12 units, crests, curls down and to the right into the 07 tube ----
271	  const s6 = pts[pts.length - 1].clone();
272	  seg(34, (t) =>
273	    V(
274	      s6.x - 4 * Math.sin(Math.PI * t) + (WORLD.chamber.center.x - s6.x) * smooth(0.4, 1, t),
275	      s6.y + 12.5 * Math.pow(Math.sin(Math.PI * Math.min(t / 0.82, 1)), 1.15) - 4.5 * smooth(0.5, 1, t),
276	      s6.z - 46 * t,
277	    ),
278	  );
279	  mark('07');
280	  // ---- 07: winding washer tube (the visible stretch) ----
281	  const s7 = pts[pts.length - 1].clone();
282	  seg(32, (t) =>
283	    V(s7.x + 3.2 * Math.sin(3 * Math.PI * t) * Math.sin(Math.PI * t), s7.y + (WORLD.plunge.topY - s7.y) * t, s7.z - 60 * t),
284	  );
285	  mark('07_plunge_top');
286	  // ---- 07: THE DEEP PLUNGE — pull-down arc, long -70° straight, pull-up arc into the 08 inlet ----
287	  const p0 = pts[pts.length - 1].clone();
288	  const R = 14;
289	  const amax = THREE.MathUtils.degToRad(70);
290	  seg(12, (t) => {
291	    const a = amax * t;
292	    return p0.clone().add(V(0, -R * (1 - Math.cos(a)), -R * Math.sin(a)));
293	  });
294	  const p1 = pts[pts.length - 1].clone();
295	  const dPl = V(0, -Math.sin(amax), -Math.cos(amax));
296	  // straight length chosen so the bottom lands exactly on the chamber floor altitude
297	  const drop = p0.y - WORLD.plunge.bottomY;
298	  const Lstraight = (drop - 2 * R * (1 - Math.cos(amax))) / Math.sin(amax);
299	  seg(Math.ceil(Lstraight / 2), (t) => p1.clone().addScaledVector(dPl, Lstraight * t));
300	  mark('07_plunge_mid_end');
301	  const p2 = pts[pts.length - 1].clone();
302	  seg(12, (t) => {
303	    const a = -amax + amax * t;
304	    return p2.clone().add(V(0, R * (Math.cos(-amax) - Math.cos(a)), R * (Math.sin(-amax) - Math.sin(a))));
305	  });
306	  mark('07_plunge_bottom');
307	  const p3 = pts[pts.length - 1].clone();
308	  const zIn = WORLD.chamber.zBack;
309	  seg(4, (t) => V(p3.x, p3.y, p3.z + (zIn - p3.z) * t));
310	  mark('08');
311	  // ---- 08–10: Final Spin Chamber — winding stream toward the platform & towel ----
312	  const s8 = pts[pts.length - 1].clone();
313	  const plat = WORLD.platform;
314	  seg(14, (t) => V(s8.x + 3.6 * Math.sin(2 * Math.PI * t) * Math.sin(Math.PI * t), s8.y, s8.z - 15 * t));
315	  mark('09');
316	  const s9 = pts[pts.length - 1].clone();
317	  seg(14, (t) => V(s9.x - 3.2 * Math.sin(Math.PI * t), s9.y + 0.1 * t, s9.z - 15 * t));
318	  mark('10');
319	  const s10 = pts[pts.length - 1].clone();
320	  const end = V(plat.center.x, plat.topY + 0.45, plat.center.z + 0.6);
321	  seg(10, (t) =>
322	    V(s10.x + (end.x - s10.x) * t, s10.y + (end.y - s10.y) * smooth(0.3, 1, t), s10.z + (end.z - s10.z) * t),
323	  );
324	  mark('11');
325	  smoothPolyline(pts, marks['03'], 2.2, 3);
326	  // 05 meander: exact lateral offset from the straight tunnel line (after smoothing, see S05)
327	  const dir05 = L05.clone().normalize();
328	  for (let i = marks['05'] + 1; i < marks['06']; i++) {
329	    const u = pts[i].clone().sub(s5).dot(dir05) * (S05.L / L05.length());
330	    pts[i].x += meander05(u);
331	  }
332	  return { points: pts, marks, straight };
333	}
334	
335	/**
336	 * Arc-length Gaussian smoothing of the polyline from index `from` to the end (endpoints fixed).
337	 * Removes tangent kinks where independently generated segments meet; the 02 tumble helix
338	 * (before `from`) is left untouched.
339	 */
340	function smoothPolyline(pts: THREE.Vector3[], from: number, sigma: number, passes: number) {
341	  for (let pass = 0; pass < passes; pass++) {
342	    const cum: number[] = [0];
343	    for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + pts[i].distanceTo(pts[i - 1]));
344	    const out = pts.map((p) => p.clone());
345	    for (let i = from + 1; i < pts.length - 1; i++) {
346	      const acc = new THREE.Vector3();
347	      let wsum = 0;
348	      for (let j = i - 12; j <= i + 12; j++) {
349	        if (j < from || j >= pts.length) continue;
350	        const d = cum[j] - cum[i];
351	        const w = Math.exp(-(d * d) / (2 * sigma * sigma));
352	        acc.addScaledVector(pts[j], w);
353	        wsum += w;
354	      }
355	      out[i].copy(acc.divideScalar(wsum));
356	    }
357	    for (let i = from + 1; i < pts.length - 1; i++) pts[i].copy(out[i]);
358	  }
