361	export class Course {
362	  readonly curve: THREE.CatmullRomCurve3;
363	  readonly length: number;
364	  readonly stages: StageDef[];
365	  readonly marks: Record<string, number>; // arc-length of named marks
366	  /** straight tunnel stretches (05 current) — see StraightAxis */
367	  readonly straightAxes: StraightAxis[];
368	  /** world X of the straight 05 tunnel line (the meander is pos.x − line05x) */
369	  private readonly line05x: number;
370	  private st05!: StageDef;
371	  private st10!: StageDef;
372	  private readonly N: number;
373	  private readonly ds: number;
374	  private readonly P: Float32Array;
375	  private readonly T: Float32Array;
376	  private readonly U: Float32Array;
