378	  constructor() {
379	    const route = buildRoute();
380	    this.curve = new THREE.CatmullRomCurve3(route.points, false, 'centripetal');
381	    // arc-length table over curve parameter u
382	    const M = route.points.length * 24;
383	    const us: number[] = [0];
384	    const ls: number[] = [0];
385	    let prev = this.curve.getPoint(0);
386	    for (let i = 1; i <= M; i++) {
387	      const u = i / M;
388	      const p = this.curve.getPoint(u);
389	      ls.push(ls[i - 1] + p.distanceTo(prev));
390	      us.push(u);
391	      prev = p;
392	    }
393	    this.length = ls[M];
394	    const uAtS = (s: number) => {
395	      let lo = 0, hi = M;
396	      while (hi - lo > 1) {
397	        const mid = (lo + hi) >> 1;
398	        if (ls[mid] < s) lo = mid; else hi = mid;
399	      }
400	      const f = (s - ls[lo]) / Math.max(1e-6, ls[hi] - ls[lo]);
401	      return us[lo] + (us[hi] - us[lo]) * f;
402	    };
403	    const sAtIndex = (i: number) => {
404	      const u = i / (route.points.length - 1);
405	      const k = Math.round(u * M);
406	      return ls[k];
407	    };
408	    this.marks = {};
409	    for (const [k, i] of Object.entries(route.marks)) this.marks[k] = sAtIndex(i);
410	    this.straightAxes = route.straight.map((r) => ({ s0: this.marks[r.from], s1: this.marks[r.to], a: r.a, b: r.b, floorDepth: r.floorDepth }));
411	    this.line05x = route.straight[0].a.x;
412	
413	    // ---- stages ----
414	    const m = this.marks;
415	    const def = (id: StageId, s0: number, s1: number, o: Partial<StageDef>): StageDef => ({
416	      id, title: STAGE_TITLES[id], s0, s1, width: 5, tube: 0, tubeKind: 'none', speed: 11, refCoins: 0,
417	      interactive: true, bank: 1, ...o,
418	    });
419	    this.stages = [
420	      def('01', 0, 0.01, { width: 6, interactive: false, speed: 0 }),
421	      def('02', 0.01, m['03'], { width: 5, interactive: false, speed: 9, bank: 0 }),
422	      def('03', m['03'], m['04'], { width: 7, speed: 9, refCoins: 1330, bank: 2.2 }),
423	      def('04', m['04'], m['05'], { width: 4.4, tube: 4.8, tubeKind: 'gold', speed: 14, refCoins: 1330 }),
424	      // 05: level current (ref 05 shows no tilt) → weak curvature banking. `width` is the hand-over
425	      // value at the 04/06 junctions; inside the current widthAt() widens the stream to fill the floor.
426	      def('05', m['05'], m['06'], { width: 9, tube: 7.6, tubeKind: 'perf', speed: 11, refCoins: 1420, bank: 0.25 }),
427	      def('06', m['06'], m['07'], { width: 7, tube: 15, tubeKind: 'perf', speed: 11, refCoins: 1680, bank: 0.6 }),
428	      def('07', m['07'], m['08'], { width: 5.6, tube: 7.2, tubeKind: 'perf', speed: 12, refCoins: 1940 }),
429	      def('08', m['08'], m['09'], { width: 4.8, speed: 9.5, refCoins: 2040 }),
430	      def('09', m['09'], m['10'], { width: 6.4, speed: 9.5, refCoins: 2280 }),
431	      def('10', m['10'], m['11'], { width: 3.8, speed: 7.5, refCoins: 2500 }),
432	      def('11', m['11'], this.length, { width: 3, interactive: false, speed: 0, refCoins: 2500 }),
433	    ];
434	
435	    // ---- dense frame table (pos, tangent, banked up) ----
436	    this.N = Math.ceil(this.length / 0.25) + 1;
437	    this.ds = this.length / (this.N - 1); // exact spacing so the last interval is not short
438	    this.P = new Float32Array(this.N * 3);
439	    this.T = new Float32Array(this.N * 3);
440	    this.U = new Float32Array(this.N * 3);
441	    const pos: THREE.Vector3[] = [];
442	    const tan: THREE.Vector3[] = [];
443	    for (let i = 0; i < this.N; i++) {
444	      const s = Math.min(this.length, i * this.ds);
445	      const u = uAtS(s);
446	      pos.push(this.curve.getPoint(u));
447	      tan.push(this.curve.getTangent(u).normalize());
448	    }
449	    // up: world-up projected off the tangent + curvature banking, then smoothed
450	    const WU = new THREE.Vector3(0, 1, 0);
451	    const ups: THREE.Vector3[] = [];
452	    let prevUp = WU.clone();
453	    for (let i = 0; i < this.N; i++) {
454	      const t = tan[i];
455	      let up = WU.clone().addScaledVector(t, -WU.dot(t));
456	      if (up.lengthSq() < 1e-4) up = prevUp.clone().addScaledVector(t, -prevUp.dot(t));
457	      up.normalize();
458	      // banking from lateral curvature
459	      const i0 = Math.max(0, i - 4), i1 = Math.min(this.N - 1, i + 4);
460	      const k = tan[i1].clone().sub(tan[i0]).divideScalar((i1 - i0) * this.ds);
461	      const right = new THREE.Vector3().crossVectors(t, up).normalize();
462	      const st = this.stageAtS(i * this.ds);
463	      const bankAngle = THREE.MathUtils.clamp(-k.dot(right) * 6 * st.bank, -0.85, 0.85);
464	      up.applyAxisAngle(t, bankAngle);
465	      ups.push(up);
466	      prevUp = up;
467	    }
468	    // smooth up vectors (box filter) & re-orthogonalize
469	    const sm: THREE.Vector3[] = ups.map((_, i) => {
470	      const acc = new THREE.Vector3();
471	      for (let j = -8; j <= 8; j++) acc.add(ups[THREE.MathUtils.clamp(i + j, 0, this.N - 1)]);
472	      const t = tan[i];
473	      return acc.addScaledVector(t, -acc.dot(t)).normalize();
474	    });
475	    for (let i = 0; i < this.N; i++) {
476	      pos[i].toArray(this.P, i * 3);
477	      tan[i].toArray(this.T, i * 3);
478	      sm[i].toArray(this.U, i * 3);
479	    }
480	    this.st05 = this.stage('05');
481	    this.st10 = this.stage('10');
482	    // '05_crest': the first meander crest (stream furthest left, heading parallel to the tunnel
483	    // axis) — the 05 QA checkpoint, where Benny faces the vanishing point down the straight tube
484	    let best = this.st05.s0 + S05.uCrest, dMin = Infinity;
485	    for (let s = this.st05.s0 + 4; s < this.st05.s0 + S05.uCrest + S05.lambda / 4; s += 0.05) {
486	      const d = this.offset05(s);
487	      if (d < dMin) { dMin = d; best = s; }
488	    }
489	    this.marks['05_crest'] = best;
490	  }
491	
492	  /** 05 current: lateral offset (units, +X) of the stream centreline from the straight tunnel line */
493	  offset05(s: number): number {
494	    const st = this.st05;
495	    if (s <= st.s0 || s >= st.s1) return 0;
496	    return this.sample(s).pos.x - this.line05x;
497	  }
498	
499	  stageAtS(s: number): StageDef {
500	    for (const st of this.stages) if (s < st.s1) return st;
501	    return this.stages[this.stages.length - 1];
502	  }
503	
504	  stage(id: StageId): StageDef {
505	    return this.stages.find((s) => s.id === id)!;
506	  }
507	
508	  /**
509	   * smoothly blended per-stage property (blend ±blend units around stage boundaries).
510	   * Accepts either argument order: prop(s, 'width') or prop('width', s).
511	   */
512	  prop(s: number, key: StageProp, blend?: number): number;
513	  prop(key: StageProp, s: number, blend?: number): number;
514	  prop(a: number | StageProp, b: number | StageProp, blend = 6): number {
515	    const s = (typeof a === 'number' ? a : b) as number;
516	    const key = (typeof a === 'string' ? a : b) as StageProp;
517	    let v = 0, w = 0;
518	    for (const st of this.stages) {
519	      const a = smooth(st.s0 - blend, st.s0 + blend, s) * (1 - smooth(st.s1 - blend, st.s1 + blend, s));
520	      if (a > 0) { v += st[key] * a; w += a; }
521	    }
522	    return w > 0 ? v / w : this.stageAtS(s)[key];
523	  }
524	
525	  widthAt(s: number): number {
526	    let base = this.prop(s, 'width');
527	    // 05 current (ref 05): the water fills the tube floor wall to wall. The centreline winds by
528	    // offset05(s), so the half width is S05.extent − |offset| (smooth abs): the outer edge of each bend
529	    // stays on the same tube chord (constant tunnel radius/depth in tube.ts) and the inner side of a
530	    // bend leaves a narrow bank for the foam, like a river.
531	    const st5 = this.st05;
532	    const k = smooth(st5.s0 + 0.5, st5.s0 + 10, s) * (1 - smooth(st5.s1 - 10, st5.s1 - 0.5, s));
533	    if (k > 0) {
534	      const d = this.offset05(s);
535	      base += (2 * (S05.extent - Math.sqrt(d * d + 0.09)) - base) * k;
536	    }
537	    // the stream narrows into the towel opening at the very end of 10
538	    const st10 = this.st10;
539	    return base * (1 - 0.35 * smooth(st10.s1 - 8, st10.s1, s));
540	  }
541	
542	  sample(s: number, out?: CourseSample): CourseSample {
543	    const o = out ?? { s: 0, pos: new THREE.Vector3(), tan: new THREE.Vector3(), up: new THREE.Vector3(), right: new THREE.Vector3() };
544	    const x = THREE.MathUtils.clamp(s, 0, this.length) / this.ds;
545	    const i = Math.min(this.N - 2, Math.floor(x));
546	    const f = x - i;
547	    const lerp3 = (A: Float32Array, v: THREE.Vector3) =>
548	      v.set(
549	        A[i * 3] + (A[i * 3 + 3] - A[i * 3]) * f,
550	        A[i * 3 + 1] + (A[i * 3 + 4] - A[i * 3 + 1]) * f,
551	        A[i * 3 + 2] + (A[i * 3 + 5] - A[i * 3 + 2]) * f,
552	      );
553	    o.s = s;
554	    lerp3(this.P, o.pos);
555	    lerp3(this.T, o.tan).normalize();
556	    lerp3(this.U, o.up);
557	    o.up.addScaledVector(o.tan, -o.up.dot(o.tan)).normalize();
558	    o.right.crossVectors(o.tan, o.up).normalize();
559	    return o;
560	  }
561	
562	  /** world position on the water at arc-length s with lateral offset (− left, + right) and height */
563	  pointAt(s: number, lateral = 0, height = 0, out = new THREE.Vector3()): THREE.Vector3 {
564	    const f = this.sample(s);
565	    return out.copy(f.pos).addScaledVector(f.right, lateral).addScaledVector(f.up, height);
566	  }
567	}
