569	export interface ContinuityReport {
570	  ok: boolean;
571	  boundaries: { from: StageId; to: StageId; s: number; posGap: number; tangentAngleDeg: number; upAngleDeg: number; altitude: number }[];
572	  maxStepTangentDeg: number;
573	  maxStepPos: number;
574	  plunge: { entryAltitude07: number; plungeTop: { s: number; y: number }; plungeMid: { s: number; y: number }; plungeBottom: { s: number; y: number }; inlet08: { s: number; y: number }; verticalDrop: number; minPitchDeg: number };
575	}
576	
577	/** Numerical continuity validation of the whole route. */
578	export function validateContinuity(c: Course): ContinuityReport {
579	  const eps = 0.02;
580	  const boundaries = c.stages.slice(0, -1).map((st, i) => {
581	    const nx = c.stages[i + 1];
582	    const sa = Math.max(st.s1 - eps, 0);
583	    const sb = Math.min(st.s1 + eps, c.length); // 11 starts at the route end (cinematic)
584	    const a = c.sample(sa);
585	    const b = c.sample(sb);
586	    return {
587	      from: st.id,
588	      to: nx.id,
589	      s: +st.s1.toFixed(2),
590	      posGap: +(a.pos.distanceTo(b.pos) - (sb - sa)).toFixed(4),
591	      tangentAngleDeg: +THREE.MathUtils.radToDeg(a.tan.angleTo(b.tan)).toFixed(3),
592	      upAngleDeg: +THREE.MathUtils.radToDeg(a.up.angleTo(b.up)).toFixed(3),
593	      altitude: +a.pos.y.toFixed(2),
594	    };
595	  });
596	  let maxT = 0, maxP = 0;
597	  const step = 0.25;
598	  let prev = c.sample(0);
599	  let minPitch = 0;
600	  const rideStart = c.stage('03').s0; // 01–02 tumble helix is a cinematic, checked for gaps only
601	  for (let s = step; s <= c.length; s += step) {
602	    const cur = c.sample(s);
603	    if (s > rideStart + step) maxT = Math.max(maxT, THREE.MathUtils.radToDeg(prev.tan.angleTo(cur.tan)));
604	    maxP = Math.max(maxP, prev.pos.distanceTo(cur.pos));
605	    if (s > c.marks['07_plunge_top'] && s < c.marks['08']) minPitch = Math.min(minPitch, THREE.MathUtils.radToDeg(Math.asin(cur.tan.y)));
606	    prev = { ...cur, pos: cur.pos.clone(), tan: cur.tan.clone(), up: cur.up.clone(), right: cur.right.clone() };
607	  }
608	  const y = (s: number) => +c.sample(s).pos.y.toFixed(2);
609	  const top = c.marks['07_plunge_top'];
610	  const bottom = c.marks['07_plunge_bottom'];
611	  const mid = (top + bottom) / 2;
612	  const inlet = c.marks['08'];
613	  const plunge = {
614	    entryAltitude07: y(c.stage('07').s0),
615	    plungeTop: { s: +top.toFixed(2), y: y(top) },
616	    plungeMid: { s: +mid.toFixed(2), y: y(mid) },
617	    plungeBottom: { s: +bottom.toFixed(2), y: y(bottom) },
618	    inlet08: { s: +inlet.toFixed(2), y: y(inlet) },
619	    verticalDrop: +(y(top) - y(inlet)).toFixed(2),
620	    minPitchDeg: +minPitch.toFixed(1),
621	  };
622	  const ok =
623	    boundaries.every((b) => Math.abs(b.posGap) < 0.01 && b.tangentAngleDeg < 1 && b.upAngleDeg < 2) &&
624	    maxP < step * 1.05 &&
625	    maxT < 8 && // ≥1.8-unit turn radius anywhere on the ride (tightest: the drop into the 03 drain)
626	    plunge.verticalDrop > 50 &&
627	    plunge.inlet08.y < plunge.entryAltitude07 - 50;
628	  return { ok, boundaries, maxStepTangentDeg: +maxT.toFixed(3), maxStepPos: +maxP.toFixed(4), plunge };
629	}
