671	      const a = rel.dot(T05);
672	      const lat = rel.addScaledVector(T05, -a).length();
673	      const k = THREE.MathUtils.smoothstep(a, aIn0, aIn1) * (1 - THREE.MathUtils.smoothstep(a, aOut0, aOut1)) * (lat < rLat ? 1 : 0);
