230	/**
231	 * Washer-tube ring collar (ref 05: "flat gold band with a double contour"): a broad FLAT inner band that
232	 * barely stands off the wall, a dark groove, then a thin raised lip on the near edge (−z, the side the
233	 * rider looks at) whose small camera-facing side catches a bright line. The protrusion is shallow on
234	 * purpose: a deep collar shows a big camera-facing annulus (the old "thick orange pipe" look, 21% gold)
235	 * and pokes through the stream where it hugs the wall (06 arch).
236	 * Lathe around local Z; radial values are fractions of the tube radius, axial values are world units
237	 * (the instance scales z by 1). Interior corners are duplicated so every facet keeps a crisp normal.
238	 */
239	export function collarGeometry(depth = 0.022, lip = 0.012, width = 1.1, segments = 96): THREE.BufferGeometry {
240	  const w = width / 2;
241	  const d = depth;
242	  const lipW = Math.min(0.16, width * 0.15), groove = Math.min(0.07, width * 0.06);
243	  // traversed from +z to -z so LatheGeometry's faces/normals point INWARD (toward the tunnel axis)
244	  const prof: [number, number][] = [
245	    [1.03, w], [1 - d * 0.5, w], // far side (hidden from the rider)
246	    [1 - d, w - 0.05], // far chamfer
247	    [1 - d, -w + lipW + groove + 0.02], // the flat band
248	    [1 - d * 0.55, -w + lipW + groove * 0.5], // dark groove (recessed toward the wall)
249	    [1 - d - lip, -w + lipW], [1 - d - lip, -w + 0.05], // raised lip
250	    [1 - d * 0.35, -w], // lip's camera-facing side → thin bright contour
251	    [1.03, -w],
252	  ];
253	  const pts: THREE.Vector2[] = [];
254	  prof.forEach(([x, y], i) => {
255	    pts.push(new THREE.Vector2(x, y));
256	    if (i > 0 && i < prof.length - 1) pts.push(new THREE.Vector2(x, y)); // crisp facet normals
257	  });
258	  const g = new THREE.LatheGeometry(pts, segments);
259	  g.rotateX(Math.PI / 2); // lathe axis Y → tube axis Z
260	  return g;
261	}
262	
263	/**
264	 * Ref 05 ring (wave 4): a ROUNDED gold band with a double contour — a thick half-round main band (the
265	 * camera-facing body catches a bright highlight on its crown and falls to copper in its shadowed lower
266	 * half) and, on the camera side (−z), a thin half-round lip separated by a narrow dark groove. Radial
267	 * values are fractions of the ring radius (1 = wall), axial values world units. Lathe around local Z,
268	 * traversed +z → −z so the faces point inward.
269	 */
270	export function roundBandGeometry(height = 0.095, width = 0.78, lipHeight = 0.045, lipWidth = 0.26, groove = 0.07, segments = 96): THREE.BufferGeometry {
271	  const w = (width + groove + lipWidth) / 2;
272	  const yc = w - width / 2, a = width / 2;
273	  const yl = -w + lipWidth / 2, al = lipWidth / 2;
274	  const pts: THREE.Vector2[] = [];
275	  const dup = (x: number, y: number) => { pts.push(new THREE.Vector2(x, y), new THREE.Vector2(x, y)); };
276	  pts.push(new THREE.Vector2(1.03, w));
277	  dup(1.0, w);
278	  for (let i = 1; i < 12; i++) {
279	    const f = (i / 12) * Math.PI;
280	    pts.push(new THREE.Vector2(1 - height * Math.sin(f), yc + a * Math.cos(f)));
281	  }
282	  dup(1.0, yc - a);
283	  pts.push(new THREE.Vector2(1.0 - height * 0.04, yc - a - groove * 0.5));
284	  dup(1.0, yl + al);
285	  for (let i = 1; i < 7; i++) {
286	    const f = (i / 7) * Math.PI;
287	    pts.push(new THREE.Vector2(1 - lipHeight * Math.sin(f), yl + al * Math.cos(f)));
288	  }
289	  dup(1.0, -w);
290	  pts.push(new THREE.Vector2(1.03, -w));
291	  const g = new THREE.LatheGeometry(pts, segments);
292	  g.rotateX(Math.PI / 2); // lathe axis Y → tube axis Z
293	  return g;
294	}
