42	/** the blended (required) numeric keys; 05-only extras (yaw, deadZone) are read directly from STAGE_CAM */
43	type BlendKey = 'back' | 'up' | 'ahead' | 'lookUp' | 'fov' | 'latFollow' | 'roll';
44	const KEYS: BlendKey[] = ['back', 'up', 'ahead', 'lookUp', 'fov', 'latFollow', 'roll'];
45	
46	export function camParamsAt(course: Course, s: number, blend = 8): CamParams {
47	  const acc: CamParams = { back: 0, up: 0, ahead: 0, lookUp: 0, fov: 0, latFollow: 0, roll: 0 };
48	  let w = 0;
49	  for (const st of course.stages) {
50	    const p = STAGE_CAM[st.id];
51	    if (!p) continue;
52	    const a = THREE.MathUtils.smoothstep(s, st.s0 - blend, st.s0 + blend) * (1 - THREE.MathUtils.smoothstep(s, st.s1 - blend, st.s1 + blend));
53	    if (a <= 0) continue;
54	    for (const k of KEYS) acc[k] += p[k] * a;
55	    w += a;
56	  }
57	  if (w === 0) return { ...(STAGE_CAM['03'] as CamParams) };
58	  for (const k of KEYS) acc[k] /= w;
59	  return acc;
60	}
