62	export class RideCamera {
63	  readonly pos = new THREE.Vector3();
64	  readonly target = new THREE.Vector3();
65	  readonly up = new THREE.Vector3(0, 1, 0);
66	  fov = 70;
67	  private init = false;
68	  /** optional straight tunnel axis + the s-range where the camera aligns to it */
