80	function standInWater(course: Course): WaterLike {
81	  const s0 = course.stage('03').s0 - 2, s1 = course.length;
82	  const n = Math.ceil((s1 - s0) / 0.5);
83	  const pos: number[] = [], idx: number[] = [];
84	  for (let i = 0; i <= n; i++) {
85	    const s = s0 + ((s1 - s0) * i) / n;
86	    const f = course.sample(s);
87	    const w = course.widthAt(s) / 2;
88	    for (const k of [-1, 1]) {
89	      const p = f.pos.clone().addScaledVector(f.right, k * w);
90	      pos.push(p.x, p.y, p.z);
91	    }
92	    if (i < n) idx.push(i * 2, i * 2 + 2, i * 2 + 1, i * 2 + 1, i * 2 + 2, i * 2 + 3);
93	  }
94	  const g = new THREE.BufferGeometry();
95	  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
96	  g.setIndex(idx);
97	  g.computeVertexNormals();
98	  const mesh = new THREE.Mesh(g, new THREE.MeshStandardMaterial({ color: '#29d6ff', emissive: '#19a6ff', emissiveIntensity: 0.5, roughness: 0.1, metalness: 0.1, side: THREE.DoubleSide }));
99	  const group = new THREE.Group();
100	  group.add(mesh);
101	  return { group, update() {}, surfaceHeight: () => 0, wake() {}, splash() {} };
102	}
103	
104	function standInBenny(): BennyRuntime {
105	  const root = new THREE.Group();
106	  const body = new THREE.Mesh(new THREE.SphereGeometry(0.8, 32, 24), new THREE.MeshStandardMaterial({ color: '#ff7ec4', roughness: 0.9 }));
107	  const hat = new THREE.Mesh(new THREE.SphereGeometry(0.84, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2), new THREE.MeshStandardMaterial({ color: '#7d3ff0' }));
108	  hat.position.y = 0.12;
109	  const pom = new THREE.Mesh(new THREE.SphereGeometry(0.38, 20, 16), new THREE.MeshStandardMaterial({ color: '#7a2de0' }));
110	  pom.position.y = 1.15;
111	  root.add(body, hat, pom);
112	  return { root, radius: 0.8, setExpression() {}, update() {} };
113	}
114	
115	function standInGirl(): GirlRuntime {
116	  const root = new THREE.Group();
117	  const mat = new THREE.MeshStandardMaterial({ color: '#c9a6f0' });
118	  const body = new THREE.Mesh(new THREE.CapsuleGeometry(3.2, 13, 8, 16), mat);
119	  body.position.y = 9.6;
120	  const head = new THREE.Mesh(new THREE.SphereGeometry(3.4, 24, 16), new THREE.MeshStandardMaterial({ color: '#f2b48a' }));
121	  head.position.y = 21.5;
122	  root.add(body, head);
123	  const handL = new THREE.Object3D(), handR = new THREE.Object3D();
124	  handL.position.set(2.5, 12, 3);
125	  handR.position.set(-2.5, 12, 3);
126	  root.add(handL, handR);
127	  const mixer = new THREE.AnimationMixer(root);
128	  return { root, mixer, play() {}, update(dt) { mixer.update(dt); }, handL, handR };
129	}
