39	export function coinLayout(course: Course): CoinDef[] {
40	  const out: CoinDef[] = [];
41	  const add = (stage: StageId, s: number, lat: number, h = 0.9, extra: Partial<CoinDef> = {}) => out.push({ s, lat, h, stage, ...extra });
42	  const st = (id: StageId) => course.stage(id);
43	  // 03 — spiral trail ahead of Benny toward the drain
44	  { const a = st('03'); for (let i = 0; i < 9; i++) add('03', a.s0 + 6 + i * 2.7, 0.9 - i * 0.12); }
45	  // 04 — along the left edge of the slide
46	  { const a = st('04'); for (let i = 0; i < 8; i++) add('04', a.s0 + 9 + i * 3.6, -1.35); }
47	  // 05 — on the winding cyan core (see C05)
48	  coins05(course, add);
49	  // 06 — up and over the crest (left of centre like the ref)
50	  { const a = st('06'); const n = 18; for (let i = 0; i < n; i++) { const s = a.s0 + 4 + i * ((a.s1 - a.s0 - 6) / n); add('06', s, -1.3 + 0.7 * Math.sin(i * 0.4)); } }
51	  // 07 — winding trail, continuing down the plunge
52	  { const a = st('07'); const n = 24; for (let i = 0; i < n; i++) { const s = a.s0 + 6 + i * ((a.s1 - a.s0 - 10) / n); add('07', s, 1.0 * Math.sin(i * 0.5 + 1)); } }
53	  // 08 — S toward the platform
54	  { const a = st('08'); for (let i = 0; i < 8; i++) add('08', a.s0 + 3 + i * 1.9, -0.6 + 0.9 * Math.sin(i * 0.8)); }
55	  // 09 — arc along the left (inside of the bend, under the wave)
56	  { const a = st('09'); for (let i = 0; i < 9; i++) add('09', a.s0 + 1.5 + i * 1.7, -1.7 + i * 0.12); }
57	  // 10 — straight line into the towel tunnel
58	  { const a = st('10'); for (let i = 0; i < 5; i++) add('10', a.s0 + 1.5 + i * 2.0, -0.15); }
59	  return out;
60	}
