72	export function createCoins(course: Course): CoinSystem {
73	  const defs = coinLayout(course);
74	  const faceTex = canvasTexture(256, 256, (c, w, h) => {
75	    const g = c.createRadialGradient(w * 0.38, h * 0.32, 10, w / 2, h / 2, w * 0.55);
76	    g.addColorStop(0, '#ffe680');
77	    g.addColorStop(0.45, '#ffcf2a');
78	    g.addColorStop(1, '#e89200');
79	    c.fillStyle = g;
80	    c.beginPath(); c.arc(w / 2, h / 2, w / 2, 0, Math.PI * 2); c.fill();
81	    // raised inner rim: dark groove + bright lip
82	    c.lineWidth = 9;
83	    c.strokeStyle = '#c98200'; c.beginPath(); c.arc(w / 2 + 2, h / 2 + 2, w * 0.4, 0, Math.PI * 2); c.stroke();
84	    c.strokeStyle = '#fff0a0'; c.beginPath(); c.arc(w / 2 - 1, h / 2 - 1, w * 0.4, 0, Math.PI * 2); c.stroke();
85	    // embossed "$" drawn as vector strokes (font-independent: identical on every Android device):
86	    // light bevel up-left, dark bevel down-right, deep-gold glyph on top
87	    const dollar = (dx: number, dy: number, col: string, lw: number) => {
88	      c.save(); c.translate(dx, dy);
89	      c.strokeStyle = col; c.lineCap = 'round'; c.lineJoin = 'round';
90	      c.lineWidth = lw;
91	      c.beginPath();
92	      c.moveTo(166, 90);
93	      c.bezierCurveTo(150, 66, 90, 64, 90, 98);
94	      c.bezierCurveTo(90, 128, 166, 124, 166, 160);
95	      c.bezierCurveTo(166, 196, 104, 198, 88, 168);
96	      c.stroke();
97	      c.lineWidth = lw * 0.62;
98	      c.beginPath(); c.moveTo(128, 50); c.lineTo(128, 206); c.stroke();
99	      c.restore();
100	    };
101	    dollar(3, 4, '#7a3c00', 32); // drop shadow
102	    dollar(0, 0, '#b86400', 30); // dark outline
103	    dollar(0, 0, '#ffe55a', 18); // bright raised glyph
104	    dollar(-3, -3, '#fff8d0', 6); // top-left bevel highlight
105	  });
106	  // the cylinder cap's UVs run sideways once the coin is stood up (rotateX): turn the face art upright
107	  faceTex.center.set(0.5, 0.5);
108	  faceTex.rotation = -Math.PI / 2;
109	  // milled (ridged) gold edge, as on the ref coins
110	  const edgeTex = canvasTexture(256, 8, (c, w, h) => {
111	    for (let x = 0; x < w; x += 4) { c.fillStyle = (x / 4) % 2 ? '#c08000' : '#ffe070'; c.fillRect(x, 0, 4, h); }
112	  });
113	  const geo = new THREE.CylinderGeometry(0.5, 0.5, 0.2, 48, 1);
114	  geo.rotateX(Math.PI / 2); // faces along ±Z
115	  // Gold is carried mostly by EMISSIVE art (blue ≈ 0) so the pink-white candy environment and the
116	  // Neutral tone mapping cannot wash it to pale peach (ref face ≈ #F4C400); a dark-gold metal base
117	  // keeps a reflective sheen on top.
118	  const side = new THREE.MeshStandardMaterial({ color: '#6a4a00', metalness: 0.75, roughness: 0.3, emissive: '#ffffff', emissiveMap: edgeTex, emissiveIntensity: 1.0 });
119	  const face = new THREE.MeshStandardMaterial({ map: faceTex, color: '#7a5200', metalness: 0.7, roughness: 0.3, emissive: '#ffffff', emissiveMap: faceTex, emissiveIntensity: 1.15 });
120	  const mesh = new THREE.InstancedMesh(geo, [side, face, face], defs.length);
121	  mesh.frustumCulled = false;
122	  const group = new THREE.Group();
123	  group.name = 'coins';
124	  group.add(mesh);
125	  const collected = new Uint8Array(defs.length);
126	  const popT = new Float32Array(defs.length).fill(-1);
127	  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), basis = new THREE.Matrix4();
128	  const p = new THREE.Vector3(), sc = new THREE.Vector3();
129	  const spin = new THREE.Quaternion(), axis = new THREE.Vector3();
130	  const tiltQ = new THREE.Quaternion(), xAxis = new THREE.Vector3(1, 0, 0);
131	  const back = new THREE.Vector3();
132	
133	  const place = (time: number) => {
134	    defs.forEach((d, i) => {
135	      const f = course.sample(d.s);
136	      let scale = 1;
137	      if (collected[i]) {
138	        if (popT[i] < 0) { sc.setScalar(0); m.compose(p.set(0, -9999, 0), q.identity(), sc); mesh.setMatrixAt(i, m); return; }
139	        const k = THREE.MathUtils.clamp((time - popT[i]) / 0.35, 0, 1);
140	        if (k >= 1) { popT[i] = -1; sc.setScalar(0); m.compose(p.set(0, -9999, 0), q.identity(), sc); mesh.setMatrixAt(i, m); return; }
141	        scale = 1 + k * 0.8;
142	        p.copy(f.pos).addScaledVector(f.right, d.lat).addScaledVector(f.up, d.h + k * 1.6);
143	      } else {
144	        p.copy(f.pos).addScaledVector(f.right, d.lat).addScaledVector(f.up, d.h + 0.08 * Math.sin(time * 3 + i));
145	      }
146	      back.copy(f.tan).negate();
147	      const right = new THREE.Vector3().crossVectors(f.up, back).normalize();
148	      basis.makeBasis(right, f.up, back);
149	      q.setFromRotationMatrix(basis);
150	      // tilted coins (05) only wobble a little so the face stays toward the camera
151	      spin.setFromAxisAngle(axis.set(0, 1, 0), (d.tilt ? 0.18 : 0.35) * Math.sin(time * 2.2 + i * 0.7));
152	      q.multiply(spin);
153	      if (d.tilt) q.multiply(tiltQ.setFromAxisAngle(xAxis, -d.tilt));
154	      m.compose(p, q, sc.setScalar((d.scale ?? 1) * scale * (collected[i] ? 1 - (time - popT[i]) / 0.35 : 1)));
155	      mesh.setMatrixAt(i, m);
156	    });
157	    mesh.instanceMatrix.needsUpdate = true;
158	  };
159	  place(0);
160	
161	  return {
162	    group,
163	    defs,
164	    collected,
165	    update(time, _dt, s, lat) {
166	      let picked = 0;
167	      for (let i = 0; i < defs.length; i++) {
168	        if (collected[i]) continue;
169	        const d = defs[i];
170	        const ds = d.s - s;
171	        if (ds < -2 || ds > 2) continue;
172	        if (Math.abs(ds) < 1.0 && Math.abs(d.lat - lat) < 1.25) {
173	          collected[i] = 1;
174	          popT[i] = time;
175	          picked++;
176	        }
177	      }
178	      place(time);
179	      return picked;
180	    },
181	    resetUntil(s) {
182	      for (let i = 0; i < defs.length; i++) { collected[i] = defs[i].s < s ? 1 : 0; popT[i] = -1; }
183	      place(0);
184	    },
185	  };
186	}
